MetricsReportingAsyncWaiter::MetricsReportingAsyncWaiter(
    MetricsReporting* proxy) : proxy_(proxy) {}

MetricsReportingAsyncWaiter::~MetricsReportingAsyncWaiter() = default;

void MetricsReportingAsyncWaiter::SetMetricsReportingEnabled(
    bool enabled) {
  base::RunLoop loop;
  proxy_->SetMetricsReportingEnabled(std::move(enabled),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








